const axios = require('axios')

/**
 * Verifies a Flutterwave transaction against the Flutterwave API.
 * Returns { valid, status, amount, currency, txRef } or throws on network error.
 *
 * @param {string|number} transactionId    - Flutterwave transaction_id from redirect
 * @param {string}        expectedTxRef    - The tx_ref generated by our app
 * @param {number}        expectedAmount   - Amount we expect to have been charged
 * @param {string}        expectedCurrency - ISO currency the charge must be in (e.g. 'NGN', 'GHS')
 */
async function verifyFlutterwaveTransaction(transactionId, expectedTxRef, expectedAmount, expectedCurrency) {
    const secretKey = process.env.FLW_SECRET_KEY

    if (!secretKey) {
        console.error('[FLW] FLW_SECRET_KEY is not set — skipping verification')
        return { valid: false, reason: 'Payment verification not configured' }
    }

    // Fail closed: without an expected currency we cannot safely confirm a charge,
    // since a cheaper currency at the same numeric amount would otherwise pass.
    if (!expectedCurrency || !String(expectedCurrency).trim()) {
        console.error('[FLW] expectedCurrency missing — refusing to verify')
        return { valid: false, reason: 'Expected currency is required to verify payment' }
    }

    try {
        const { data: body } = await axios.get(
            `https://api.flutterwave.com/v3/transactions/${transactionId}/verify`,
            { headers: { Authorization: `Bearer ${secretKey}` }, timeout: 10000 }
        )

        if (body.status !== 'success') {
            return { valid: false, reason: `Flutterwave returned status: ${body.status}` }
        }

        const txData = body.data
        const status = txData?.status?.toLowerCase()

        if (status !== 'successful') {
            return { valid: false, reason: `Transaction status is ${txData?.status}` }
        }

        if (txData.tx_ref !== expectedTxRef) {
            return { valid: false, reason: 'Transaction reference mismatch' }
        }

        const paidCurrency = String(txData.currency || '').trim().toUpperCase()
        const wantCurrency = String(expectedCurrency).trim().toUpperCase()

        if (paidCurrency !== wantCurrency) {
            return {
                valid: false,
                reason: `Currency mismatch — expected ${wantCurrency}, got ${paidCurrency || 'none'}`,
            }
        }

        if (txData.amount < expectedAmount) {
            return {
                valid: false,
                reason: `Amount mismatch — expected ${expectedAmount}, got ${txData.amount}`,
            }
        }

        return {
            valid: true,
            status: txData.status,
            amount: txData.amount,
            currency: txData.currency,
            txRef: txData.tx_ref,
        }
    } catch (err) {
        console.error('[FLW] Verification request failed:', err.message)
        return { valid: false, reason: 'Could not reach Flutterwave to verify payment' }
    }
}

module.exports = { verifyFlutterwaveTransaction }
